new=""" const queryPeople=Number(new URLSearchParams(location.search).get('people')||0);\n document.querySelector('#searchAvailability').onclick=async()=>{const a=parseUserDate(start.value),b=parseUserDate(end.value);if(!a||!b||b<a){msg.textContent='Introduce un rango de fechas válido.';return;}const available=spaces.filter(s=>{const m=maps.get(s.id)||new Map();const dateOk=!rangeHasUnavailable(a,b,m);const capacityOk=!queryPeople||(Number(s.capacity)>=queryPeople);return dateOk&&capacityOk});if(!available.length){results.innerHTML='<div class=\"empty-state\"><p>No hay espacios disponibles para estas fechas'+(queryPeople?` y para ${queryPeople} personas.`:'.')+'</p><button class=\"btn btn-light\" type=\"button\" id=\"changeDates\">Cambiar fechas</button><a class=\"btn btn-dark\" href=\"espacios.html\">Ver todos los espacios</a></div>';document.querySelector('#changeDates')?.addEventListener('click',()=>start.focus());msg.textContent='';return;}msg.textContent=queryPeople?`Mostrando espacios disponibles con aforo para ${queryPeople} personas.`:'';results.innerHTML=available.sort((x,y)=>x.name.localeCompare(y.name,'es')).map(s=>`<a class=\"space-tile\" href=\"espacio.html?id=${encodeURIComponent(s.id)}#disponibilidad\"><div class=\"space-tile-photo\"><img src=\"${esc(s.image)}\" alt=\"${esc(s.name)}\"></div><div class=\"space-tile-info\"><h2>${esc(s.name)}</h2><p>${esc(s.city)} · ${esc(s.province)}</p><div class=\"space-tile-price\">${esc(priceRange(s))}</div><span class=\"btn btn-dark\">Ver espacio y solicitar</span></div></a>`).join('');};\n"""
